-- ============================================================
-- Migration 179 -- IELTS Academic Crash Course, Class 3: a reading class (lessons + quiz, then Reading Test 1)
--
-- Generated by database/quizzes/build_ielts_aca_crash_class3.py -- edit that, not this file.
-- Founder, 2026-10-28: "Let's move on to Class 3. Same idea/s as Class 2" (178): lessons and a quiz in the first hour,
-- the practice test in the second. Class 3 had Reading Test 1 first with no reading teaching, then a Writing Task 1
-- lesson. Class 3 becomes:
--   1 IELTS Reading: Overview                       lesson  (named slot for the founder's remade video + format/timing)
--   2 True/False/Not Given & Yes/No/Not Given       lesson  (official sample: identifying writer's views + a drill)
--   3 Completion: Notes, Summary, Table & Diagram   lesson  (official samples: table + diagram completion, a summary)
--   4 Matching & Multiple Choice                    lesson  (official samples: information, headings, MC, features)
--   5 Class 3 Reading Quiz                          quiz    (IELTS_ACA_C3_RQUIZ, 20 questions, pass 70%)
--   6 Reading Test 1                                practice test (unchanged)
-- Trend Vocabulary & Paraphrasing (a Writing Task 1 lesson) leaves Class 3 for Class 5, straight before Writing Test 1
-- (Timed) -- only where Class 5 holds Writing Test 1; otherwise it stays in Class 3, after the test. Its page is now
-- class05_p2_trend-vocabulary-paraphrasing.php wherever it sits.
-- Found by folder + week + class, never by id; class ids kept (progress stays). Positions are parked at +100 first
-- (lesson_parts is unique on lesson_id + part_order). Re-runnable. MySQL 5.7-safe, no lookups in system databases.
-- Needs the files: courses/IELTS_Aca_1Mo/lessons/class03_p1..p4_*.php, class05_p2_trend-vocabulary-paraphrasing.php,
-- listening_kit.php. The SELECT at the end lists Class 3 and Class 5.
-- ============================================================

SET NAMES utf8mb4;

-- ---------------- The quiz ----------------
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'How is IELTS Academic Reading made up?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 1;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In the paper-based test, when must your answers be on the answer sheet?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 2;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Which passage is usually the longest and hardest?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 3;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Where do IELTS Academic Reading passages come from?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 4;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What is skimming?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 5;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What is scanning?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 6;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Which question types do NOT necessarily follow the order of the passage?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 7;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'What is the difference between True/False/Not Given and Yes/No/Not Given?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 8;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'The passage says the opposite of the statement. What is the answer?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 9;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'Passage: "Fertiliser use doubled in Denmark between 1960 and 1985." Statement: "Danish farmers used more fertiliser than British farmers." What is the answer?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 10;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'You know from your own knowledge that a statement is true, but the passage does not mention it. What is the answer?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 11;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'The writer says smoking causes "30 per cent of all deaths from cancer". Statement: "Thirty per cent of deaths in the United States are caused by smoking." What is the answer?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 12;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'The instruction says "NO MORE THAN THREE WORDS". You write four words with the right meaning. What happens?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 13;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'The passage says "temperate-climate Spanish species". The table''s gap is under "Preferred climate". What do you write?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 14;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In a completion task that uses words from the passage, how should you write them?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 15;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In a summary completed from a list of phrases, what is usually true?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 16;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'The gap comes straight after the word "a". What does the gap probably need?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 17;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In matching headings, what does the right heading describe?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 18;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = '"Which paragraph contains the following information?" What is true of this question type?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 19;
UPDATE questions x JOIN tests t ON t.id = x.test_id SET x.question_text = 'In multiple choice, what are the wrong options often like?' WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number = 20;
DELETE o FROM question_options o JOIN questions x ON x.id = o.question_id JOIN tests t ON t.id = x.test_id WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number > 20;
DELETE x FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'IELTS_ACA_C3_RQUIZ' AND x.question_number > 20;

-- ---------------- Class 3 (Week 2, first class) ----------------
-- The classes, as variables (a scalar subquery, no derived tables). NULL on a course without them: every statement
-- below then matches nothing.
SET @c3 := (SELECT l.id FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id WHERE c.folder_name = 'IELTS_Aca_1Mo' AND m.module_order = 2 AND l.lesson_order = 1);
SET @c5 := (SELECT l.id FROM lessons l JOIN modules m ON m.id = l.module_id JOIN courses c ON c.id = l.course_id WHERE c.folder_name = 'IELTS_Aca_1Mo' AND m.module_order = 3 AND l.lesson_order = 1);
-- Trend Vocabulary goes to Class 5 only if Class 5 holds Writing Test 1, and lands straight before it.
SET @wt := (SELECT MIN(part_order) FROM lesson_parts WHERE lesson_id = @c5 AND title = 'Writing Test 1 (Timed)');

-- The page was renamed: point every row at the new file, wherever it sits.
UPDATE lesson_parts SET file_path = 'courses/IELTS_Aca_1Mo/lessons/class05_p2_trend-vocabulary-paraphrasing.php' WHERE file_path = 'courses/IELTS_Aca_1Mo/lessons/class03_p2_trend-vocabulary-paraphrasing.php';

-- Trend Vocabulary: Class 3 -> Class 5, in Writing Test 1's place (it and everything after move one down, via +100).
UPDATE lesson_parts SET part_order = part_order + 100 WHERE lesson_id = @c5 AND @wt IS NOT NULL AND part_order >= @wt AND part_order < 100
   AND EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'Trend Vocabulary & Paraphrasing');
UPDATE lesson_parts SET lesson_id = @c5, part_order = @wt WHERE lesson_id = @c3 AND title = 'Trend Vocabulary & Paraphrasing' AND @wt IS NOT NULL;
UPDATE lesson_parts SET part_order = part_order - 99 WHERE lesson_id = @c5 AND part_order > 100;

-- Class 3's items park at +100; the six below then take places 1-6.
UPDATE lesson_parts SET part_order = part_order + 100 WHERE lesson_id = @c3 AND part_order < 100;
UPDATE lesson_parts SET part_order = 1, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class03_p1_ielts-reading-overview.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c3 AND title = 'IELTS Reading: Overview';
SELECT @c3, 1, 'IELTS Reading: Overview', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class03_p1_ielts-reading-overview.php', NULL, NULL FROM DUAL
 WHERE @c3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'IELTS Reading: Overview');
UPDATE lesson_parts SET part_order = 2, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class03_p2_true-false-not-given.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c3 AND title = 'True/False/Not Given & Yes/No/Not Given';
SELECT @c3, 2, 'True/False/Not Given & Yes/No/Not Given', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class03_p2_true-false-not-given.php', NULL, NULL FROM DUAL
 WHERE @c3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'True/False/Not Given & Yes/No/Not Given');
UPDATE lesson_parts SET part_order = 3, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class03_p3_completion-tasks.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c3 AND title = 'Completion: Notes, Summary, Table & Diagram';
SELECT @c3, 3, 'Completion: Notes, Summary, Table & Diagram', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class03_p3_completion-tasks.php', NULL, NULL FROM DUAL
 WHERE @c3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'Completion: Notes, Summary, Table & Diagram');
UPDATE lesson_parts SET part_order = 4, kind = 'lesson', status = 'ready', file_path = 'courses/IELTS_Aca_1Mo/lessons/class03_p4_matching-multiple-choice.php', test_code = NULL, pass_percent = NULL WHERE lesson_id = @c3 AND title = 'Matching & Multiple Choice';
SELECT @c3, 4, 'Matching & Multiple Choice', 'lesson', 'ready', 'courses/IELTS_Aca_1Mo/lessons/class03_p4_matching-multiple-choice.php', NULL, NULL FROM DUAL
 WHERE @c3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'Matching & Multiple Choice');
UPDATE lesson_parts SET part_order = 5, kind = 'quiz', status = 'ready', file_path = 'resources/quizzes/class_quiz.php?test_code=IELTS_ACA_C3_RQUIZ', test_code = 'IELTS_ACA_C3_RQUIZ', pass_percent = 70 WHERE lesson_id = @c3 AND title = 'Class 3 Reading Quiz';
SELECT @c3, 5, 'Class 3 Reading Quiz', 'quiz', 'ready', 'resources/quizzes/class_quiz.php?test_code=IELTS_ACA_C3_RQUIZ', 'IELTS_ACA_C3_RQUIZ', 70 FROM DUAL
 WHERE @c3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'Class 3 Reading Quiz');
UPDATE lesson_parts SET part_order = 6, kind = 'practice_test', status = 'ready', file_path = 'resources/practice_tests/ielts_reading_academic_c17_t1.php', test_code = 'IELTS_PT_R_ACA_C17T1', pass_percent = NULL WHERE lesson_id = @c3 AND title = 'Reading Test 1';
SELECT @c3, 6, 'Reading Test 1', 'practice_test', 'ready', 'resources/practice_tests/ielts_reading_academic_c17_t1.php', 'IELTS_PT_R_ACA_C17T1', NULL FROM DUAL
 WHERE @c3 IS NOT NULL AND NOT EXISTS (SELECT 1 FROM (SELECT lesson_id, title FROM lesson_parts) y WHERE y.lesson_id = @c3 AND y.title = 'Reading Test 1');
-- Anything else still parked in Class 3 (an item this migration doesn't know) goes after the test, in its order.
UPDATE lesson_parts SET part_order = part_order - 93 WHERE lesson_id = @c3 AND part_order > 100;

-- The classes' titles list their items (rendered by includes/lesson_title.php); Class 3 is now a reading class.
UPDATE lessons SET title = (SELECT GROUP_CONCAT(p.title ORDER BY p.part_order SEPARATOR ' + ') FROM lesson_parts p WHERE p.lesson_id = @c3), icon = 'bi-book', duration_minutes = 120 WHERE id = @c3;
UPDATE lessons SET title = (SELECT GROUP_CONCAT(p.title ORDER BY p.part_order SEPARATOR ' + ') FROM lesson_parts p WHERE p.lesson_id = @c5) WHERE id = @c5 AND @wt IS NOT NULL;

SELECT CASE WHEN p.lesson_id = @c3 THEN 'Class 3' ELSE 'Class 5' END AS class, p.part_order, p.title, p.kind, p.status, p.file_path
  FROM lesson_parts p WHERE p.lesson_id IN (@c3, @c5) ORDER BY p.lesson_id = @c5, p.part_order;
SELECT COUNT(*) AS quiz_questions FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'IELTS_ACA_C3_RQUIZ';
